let objs;

function setup() {
	const mwh = max(windowWidth, windowHeight);
	const ar = windowWidth / windowHeight;
	createCanvas(mwh * ar, mwh / ar); // createCanvas(mw , mw*9/16);
	frameRate(60);

	objs = [];
	objs.push(new BasicShape(1, height*0.5, mwh, 0.8, PI, color(222)));
	objs.push(new BasicShape(2, height*0.5, mwh, 0.9, HALF_PI, color(16)));
	objs.push(new BasicShape(3, height*0.5, mwh, 0.5, TWO_PI, color(222)));
}

function windowResized() {
	setup();
}

function draw() {
	blendMode(BLEND)
	background(16);

	noFill();
	stroke("white")
	rect(1, 1, width-2, height-2);
	// blendMode(DIFFERENCE)
	for (let o of objs) {
		o.update();
		o.show();
	}
}

class BasicShape {
	constructor(typ, yps, sze, scl, ang, clr) {
		this.typ = typ;
		this.xps = 0;
		this.yps = yps;
		this.sze = sze;
		this.scl = scl;
		this.ang = ang;
		this.clr = clr;
	}
	update() {
		this.ang += 0.05;
		this.xps = cos(this.ang) * (width - this.sze) * 0.5 + width * 0.5;
	}
	show() {
		push();
		noStroke()
		fill(this.clr)

		if (this.typ === 1) this.showRect();
		if (this.typ === 2) this.showCircle();
		if (this.typ === 3) this.showTri();

		pop();
	}

	showRect() {
		rectMode(CENTER)
		translate(this.xps, this.yps);
		rotate(this.ang);
		rect(0, 0, this.sze * this.scl * 0.5, this.sze * this.scl * 0.5)
	}
	showCircle() {
		circle(this.xps, this.yps, this.sze * this.scl * 0.5)
	}
	showTri() {
		const s_h = this.sze * this.scl * 0.5;
		triangle(this.xps - s_h, this.yps + s_h, this.xps, this.yps - s_h, this.xps + s_h, this.yps + s_h)
	}
}
